// src/lib/api-client.ts
// The typed openapi-fetch client — the ONLY place raw HTTP is issued. Hooks in
// src/hooks/ call apiClient.GET/POST/…; features/components/pages never touch it.
// Types come from the generated contract (@/types/api.generated), regenerated by
// /api-sync — never hand-edited.
import createClient from 'openapi-fetch'
import type { paths } from '@/types/api.generated'
import { env } from '@/lib/env'

export const apiClient = createClient<paths>({
  baseUrl: env.NEXT_PUBLIC_API_URL,
  // REQUIRED lazy fetch: openapi-fetch binds globalThis.fetch at client-creation time,
  // which happens at import (before MSW patches fetch in beforeAll). Wrapping it means
  // every call re-reads globalThis.fetch, so MSW can intercept in tests.
  fetch: (...args) => globalThis.fetch(...args),
})
